'use client';

import {
  CreateItemCategoryRequest,
  UpdateItemCategoryRequest,
  type ItemCategoryResponse,
} from '@uie/contracts';
import { useState } from 'react';
import { z } from 'zod';
import { FormLayout, TextField } from '@/components/erp';
import { Dialog, DialogContent, DialogDescription, DialogTitle } from '@/components/ui/dialog';
import { terminology } from '@/config/terminology';
import { apiRequest, messageForApiError } from '@/lib/api/client';
import * as toast from '@/lib/toast';

// The code (IG-0001) is generated by the API, so the form only has the name.
const schema = z.object({
  name: z.string().trim().min(1, terminology.validation.required).max(100),
});

type CategoryFormValues = z.infer<typeof schema>;

export interface CategoryDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  /** Present when editing an existing category. */
  category?: ItemCategoryResponse;
  onSaved: () => void;
}

export function CategoryDialog({ open, onOpenChange, category, onSaved }: CategoryDialogProps) {
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const isEdit = category !== undefined;

  // Defaults are only read when the form mounts (the dialog is keyed by category id).
  const [defaults] = useState<CategoryFormValues>(() => ({ name: category?.name ?? '' }));

  async function handleSubmit(values: CategoryFormValues): Promise<void> {
    setErrorMessage(null);

    // Validate once more against the real API contract before sending.
    const checked = isEdit
      ? UpdateItemCategoryRequest.safeParse(values)
      : CreateItemCategoryRequest.safeParse(values);

    if (!checked.success) {
      setErrorMessage(terminology.apiErrors.VALIDATION_ERROR);
      return;
    }

    const result = isEdit
      ? await apiRequest('PATCH', `/api/item-categories/${category.id}`, checked.data)
      : await apiRequest('POST', '/api/item-categories', checked.data);

    if (!result.ok) {
      setErrorMessage(messageForApiError(result.code));
      return;
    }

    toast.success(isEdit ? terminology.itemCategories.updated : terminology.itemCategories.created);
    onOpenChange(false);
    onSaved();
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <div className="mb-3 space-y-1">
          <DialogTitle>
            {isEdit ? terminology.itemCategories.editTitle : terminology.itemCategories.addTitle}
          </DialogTitle>
          <DialogDescription className="text-sm text-muted-foreground">
            {isEdit ? category.code : terminology.itemCategories.codeAutoHint}
          </DialogDescription>
        </div>
        {errorMessage === null ? null : (
          <p role="alert" className="mb-3 text-sm text-danger">
            {errorMessage}
          </p>
        )}
        <FormLayout<CategoryFormValues>
          schema={schema}
          defaultValues={defaults}
          onSubmit={handleSubmit}
          onCancel={() => onOpenChange(false)}
        >
          <div className="grid gap-4">
            <TextField<CategoryFormValues>
              name="name"
              label={terminology.itemCategories.fieldName}
              description={terminology.itemCategories.fieldNameHint}
              required
            />
          </div>
        </FormLayout>
      </DialogContent>
    </Dialog>
  );
}
